//! Exact factory frames generated by ML Plasma. Playback uses Wave's own engine.
use crate::wavetable::{MAX_FRAMES, PLASMA_SIZE, Source};
use std::sync::OnceLock;

type Entry = (&'static str, &'static [u8]);
const PACK: &[u8] = include_bytes!("../assets/plasma-wavetables.pwt");

fn take(bytes: &mut &'static [u8], len: usize) -> Option<&'static [u8]> {
    let (value, rest) = bytes.split_at_checked(len)?;
    *bytes = rest;
    Some(value)
}

fn number(bytes: &mut &'static [u8]) -> Option<usize> {
    Some(u32::from_le_bytes(take(bytes, 4)?.try_into().ok()?) as usize)
}

fn decode(mut bytes: &'static [u8]) -> Option<Vec<Entry>> {
    if take(&mut bytes, 4)? != b"PWT1" || number(&mut bytes)? != PLASMA_SIZE {
        return None;
    }
    let count = number(&mut bytes)?;
    if count > 128 { return None; }
    let mut entries = Vec::with_capacity(count);
    for _ in 0..count {
        let name_len = number(&mut bytes)?;
        let frames = number(&mut bytes)?;
        if !(1..=256).contains(&name_len) || !(1..=MAX_FRAMES).contains(&frames) {
            return None;
        }
        let name = std::str::from_utf8(take(&mut bytes, name_len)?).ok()?;
        let samples = take(&mut bytes, frames * PLASMA_SIZE * size_of::<f32>())?;
        entries.push((name, samples));
    }
    bytes.is_empty().then_some(entries)
}

fn entries() -> &'static [Entry] {
    static ENTRIES: OnceLock<Vec<Entry>> = OnceLock::new();
    ENTRIES.get_or_init(|| decode(PACK).unwrap_or_default())
}

pub fn names() -> impl Iterator<Item = &'static str> {
    entries().iter().map(|&(name, _)| name)
}

pub fn load(index: usize) -> Result<Source, String> {
    let &(name, bytes) = entries().get(index).ok_or("Plasma wavetable unavailable")?;
    let source = Source {
        name: name.into(),
        frame_size: PLASMA_SIZE,
        samples: bytes.chunks_exact(4)
            .map(|word| f32::from_le_bytes(word.try_into().unwrap()))
            .collect(),
    };
    source.validate()?;
    Ok(source)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn complete_plasma_factory_pack_has_original_frames() {
        let names: Vec<_> = names().collect();
        assert_eq!(names.len(), 22);
        assert_eq!(names.iter().copied().collect::<std::collections::BTreeSet<_>>().len(), names.len());
        assert_eq!(names[0], "Basic Shapes");
        assert_eq!(names[21], "Resonance Sweep");
        let mut frames = 0;
        for (i, name) in names.into_iter().enumerate() {
            let table = load(i).unwrap();
            assert_eq!(table.name, name);
            assert_eq!(table.frame_size, PLASMA_SIZE);
            if i == 0 { assert_eq!(table.frames(), 64); }
            for frame in table.samples.chunks_exact(PLASMA_SIZE) {
                assert!(frame.iter().any(|v| v.abs() > 0.95), "{name}");
            }
            frames += table.frames();
        }
        assert_eq!(frames, 576);
    }
}
